 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    if h == 0:
        return out
    for c in range(w):
        if out[h - 1][c] != 5:
            continue
        seeds = [r for r in range(h - 1) if out[r][c] != 0]
        # The 5 marker fills the blank region up to the lowest colored seed.
        low = seeds[-1] if seeds else -1
        for r in range(low + 1, h - 1):
            out[r][c] = 5
        # Between seeds, the lower seed's color fills the intervening gap.
        for i in range(len(seeds) - 1):
            upper, lower = seeds[i], seeds[i + 1]
            color = out[lower][c]
            for r in range(upper + 1, lower):
                out[r][c] = color
        # Extend the topmost seed color to the top edge.
        if seeds:
            color = out[seeds[0]][c]
            for r in range(seeds[0]):
                out[r][c] = color
    return out
